INSERT INTO question_translations (question_id,language_code,question_text) SELECT id,'gu','જો તમે ''પોસ્ટ મેનોપોઝલ'', ''પોસ્ટ હિસ્ટ્રેક્ટમી'' અથવા ''પોસ્ટ ઓઓફોરેક્ટમી'' પર જવાબ આપ્યો હોય તો, તમે કયા વર્ષની ઉંમરે મેનોપોઝ પ્રાપ્ત કરી અથવા શસ્ત્રક્રિયા કરી?' FROM questions WHERE version_number=2 AND question_key='V2_Q11B' ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
