-- Updated V2 question translations. Review before COMMIT.
SET NAMES utf8mb4;
USE bcd_application2;
START TRANSACTION;


SELECT qt.language_code,COUNT(*) AS translated_questions
FROM question_translations qt JOIN questions q ON q.id=qt.question_id
WHERE q.version_number=2 AND q.question_key IN ('V2_Q02','V2_Q11B','V2_Q11_CYCLES','V2_Q13','V2_Q13A','V2_Q13B','V2_Q13C','V2_Q13C_TRIMESTERS','V2_Q13D','V2_Q13D_TRIMESTERS','V2_Q13E','V2_Q13_AGE_FIRST_BIRTH')
GROUP BY qt.language_code ORDER BY qt.language_code;
-- Deliberately no COMMIT.
